#!/usr/bin/env python3
"""Independent experimental HPKE SHA3 key-schedule vectors."""

import hashlib
import hmac


KDF_ID = 0xFF01
NH = 32
VERSION = b"HPKE-v1"


def extract(salt, ikm):
    if not salt:
        salt = bytes(NH)

    return hmac.new(
        salt, ikm, hashlib.sha3_256
    ).digest()


def expand(prk, info, length):
    if not 0 <= length <= 255 * NH:
        raise ValueError("Invalid HKDF output length")

    if len(prk) < NH:
        raise ValueError("Invalid HKDF PRK length")

    result = bytearray()
    block = b""

    for counter in range(1, (length + NH - 1) // NH + 1):
        block = hmac.new(
            prk,
            block + info + bytes([counter]),
            hashlib.sha3_256,
        ).digest()

        result.extend(block)

    return bytes(result[:length])


def labeled_extract(suite, salt, label, ikm):
    return extract(
        salt,
        VERSION + suite + label + ikm,
    )


def labeled_expand(suite, prk, label, info, length):
    labeled_info = (
        length.to_bytes(2, "big")
        + VERSION
        + suite
        + label
        + info
    )

    return expand(prk, labeled_info, length)


def key_schedule(kem_id, aead_id, key_length, mode):
    suite = (
        b"HPKE"
        + kem_id.to_bytes(2, "big")
        + KDF_ID.to_bytes(2, "big")
        + aead_id.to_bytes(2, "big")
    )

    # Synthetic, deterministic key-schedule input.
    # This is not generated by a KEM.
    shared_secret = bytes(range(32))

    info = b"pqc-rs/experimental/sha3/key-schedule/v1"

    if mode == 0:
        psk = b""
        psk_id = b""
    elif mode == 1:
        psk = bytes(range(32, 64))
        psk_id = b"experimental-psk-01"
    else:
        raise ValueError("Unsupported test mode")

    psk_id_hash = labeled_extract(
        suite, b"", b"psk_id_hash", psk_id
    )

    info_hash = labeled_extract(
        suite, b"", b"info_hash", info
    )

    context = bytes([mode]) + psk_id_hash + info_hash

    secret = labeled_extract(
        suite, shared_secret, b"secret", psk
    )

    key = labeled_expand(
        suite, secret, b"key", context, key_length
    )

    nonce = labeled_expand(
        suite, secret, b"base_nonce", context, 12
    )

    exporter_secret = labeled_expand(
        suite, secret, b"exp", context, NH
    )

    exporter_context = b"independent-export-context"

    exported = labeled_expand(
        suite,
        exporter_secret,
        b"sec",
        exporter_context,
        80,
    )

    return [
        f"{kem_id:04x}",
        f"{aead_id:04x}",
        str(mode),
        shared_secret.hex(),
        info.hex(),
        psk.hex(),
        psk_id.hex(),
        suite.hex(),
        context.hex(),
        secret.hex(),
        key.hex(),
        nonce.hex(),
        exporter_secret.hex(),
        exporter_context.hex(),
        exported.hex(),
    ]


def main():
    print(
        "# kem_id\taead_id\tmode\tshared_secret"
        "\tinfo\tpsk\tpsk_id\tsuite"
        "\tkey_schedule_context\tsecret"
        "\tkey\tbase_nonce\texporter_secret"
        "\texporter_context\texported"
    )

    count = 0

    for kem_id in (0x0041, 0x647A):
        for aead_id, key_length in (
            (0x0001, 16),
            (0x0002, 32),
            (0x0003, 32),
        ):
            for mode in (0, 1):
                print(
                    "\t".join(
                        key_schedule(
                            kem_id,
                            aead_id,
                            key_length,
                            mode,
                        )
                    )
                )

                count += 1

    assert count == 12


if __name__ == "__main__":
    main()
